-- M1 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE identity.organizations (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL UNIQUE, name text NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON identity.organizations TO helpdesk_m1;
CREATE TABLE identity.subjects (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), kind text NOT NULL CHECK(kind IN ('PUBLIC','ASN','STAFF','VENDOR','SERVICE')), external_ref text UNIQUE, active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON identity.subjects TO helpdesk_m1;
CREATE TABLE identity.teams (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), org_id uuid NOT NULL REFERENCES identity.organizations(id), name text NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON identity.teams TO helpdesk_m1;
CREATE TABLE identity.memberships (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), subject_id uuid NOT NULL REFERENCES identity.subjects(id), org_id uuid NOT NULL REFERENCES identity.organizations(id), team_id uuid REFERENCES identity.teams(id), permissions text[] NOT NULL, valid_until timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(subject_id,org_id,team_id));
GRANT SELECT, INSERT, UPDATE ON identity.memberships TO helpdesk_m1;
CREATE TABLE identity.sessions (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), subject_id uuid NOT NULL REFERENCES identity.subjects(id), token_hash bytea NOT NULL UNIQUE CHECK(octet_length(token_hash)=32), csrf_hash bytea NOT NULL CHECK(octet_length(csrf_hash)=32), expires_at timestamptz NOT NULL, revoked_at timestamptz);
GRANT SELECT, INSERT, UPDATE ON identity.sessions TO helpdesk_m1;
CREATE TABLE identity.delegations (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), grantor_id uuid NOT NULL REFERENCES identity.subjects(id), grantee_id uuid NOT NULL REFERENCES identity.subjects(id), org_id uuid NOT NULL REFERENCES identity.organizations(id), permissions text[] NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, reason text NOT NULL);
GRANT SELECT, INSERT, UPDATE ON identity.delegations TO helpdesk_m1;
CREATE TABLE identity.api_clients (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL, credential_ref text NOT NULL, scopes text[] NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
GRANT SELECT, INSERT, UPDATE ON identity.api_clients TO helpdesk_m1;
CREATE TABLE identity.maintenance_policies (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), org_id uuid REFERENCES identity.organizations(id), mode text NOT NULL CHECK(mode IN ('READ_ONLY','DRAIN')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, message text NOT NULL, CHECK(ends_at>starts_at));
GRANT SELECT, INSERT, UPDATE ON identity.maintenance_policies TO helpdesk_m1;
CREATE TABLE identity.system_operation_requests (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), kind text NOT NULL CHECK(kind IN ('BACKUP_MANIFEST','HEALTH_REPORT','PURGE_REQUEST')), requested_by uuid NOT NULL REFERENCES identity.subjects(id), target_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','RUNNING','SUCCEEDED','FAILED','DISABLED')), reason text NOT NULL, approved_by uuid REFERENCES identity.subjects(id), CHECK(approved_by IS NULL OR approved_by<>requested_by));
GRANT SELECT, INSERT, UPDATE ON identity.system_operation_requests TO helpdesk_m1;
CREATE TABLE identity.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE identity.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE identity.outbox_delivery (event_id uuid NOT NULL REFERENCES identity.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE identity.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE identity.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON identity.idempotency_records, identity.outbox, identity.inbox, identity.audit_intents TO helpdesk_m1;
GRANT SELECT, INSERT, UPDATE ON identity.outbox_delivery TO helpdesk_m1;
CREATE INDEX ON identity.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
REVOKE ALL ON ALL TABLES IN SCHEMA identity FROM PUBLIC;
